INSERT INTO `wp_posts` VALUES (106,1,'2020-05-12 07:32:15','2020-05-12 07:32:15','<p>PTUJ, SLOVENIA</p>					<h1>LuxSpa Vesna</h1>				\n					300€&nbsp;per day				\n															<img width=\"47\" height=\"44\" src=\"http://localhost:8888/viktorin/wp-content/uploads/2020/05/book-icon-home.svg\" alt=\"\" />																<p>BOOK NOW</p>					APARTMENT				\n				<select\n			class=\"jet-select__control\"\n			name=\"yacht-types\"\n						aria-label=\"Yacht Type Select\"\n		>\n										<option\n					value=\"\"\n					data-label=\"Type\"\n					data-counter-prefix=\"\"\n					data-counter-suffix=\"\"\n														>\n					Type				</option>\n								<option\n					value=\"Sports Cruiser \"\n					data-label=\"sports-cruiser \"\n					data-counter-prefix=\"\"\n					data-counter-suffix=\"\"\n														>\n					sports-cruiser 				</option>\n								<option\n					value=\"sedan-bridge \"\n					data-label=\"Sedan Bridge \"\n					data-counter-prefix=\"\"\n					data-counter-suffix=\"\"\n														>\n					Sedan Bridge 				</option>\n								<option\n					value=\"cockpit-motor-yacht \"\n					data-label=\"Cockpit Motor Yacht \"\n					data-counter-prefix=\"\"\n					data-counter-suffix=\"\"\n														>\n					Cockpit Motor Yacht 				</option>\n								<option\n					value=\"motor-yacht \"\n					data-label=\"Motor Yacht \"\n					data-counter-prefix=\"\"\n					data-counter-suffix=\"\"\n														>\n					Motor Yacht 				</option>\n				</select>\n					Check In				\n	<fieldset>\n		<legend style=\"display:none;\">Check In</legend>\n		<input\n			class=\"jet-date-range__from jet-date-range__control\"\n			type=\"text\"\n			autocomplete=\"off\"\n			placeholder=\"Date\"\n			name=\"yacht-check-in_from\"\n			value=\"\"\n			aria-label=\"Date range from\"\n					>\n		<input\n			class=\"jet-date-range__to jet-date-range__control\"\n			type=\"text\"\n			autocomplete=\"off\"\n			placeholder=\"Date\"\n			name=\"yacht-check-in_to\"\n			value=\"\"\n			aria-label=\"Date range to\"\n					>\n	</fieldset