INSERT INTO `wp_posts` VALUES (149,1,'2020-05-12 12:09:16','2020-05-12 12:09:16','<p>SLOVENIA</p>					<h1>PTUJ</h1>				\n					299€&nbsp;per night				\n					<figure><img width=\"47\" height=\"44\" src=\"http://localhost:8888/viktorin/wp-content/uploads/2020/05/book-icon-home.svg\" alt=\"\" /></figure>BOOK NOW					APARTMENT				\n				<select\n			class=\"jet-select__control\"\n			name=\"yacht-types\"\n						aria-label=\"Yacht Type Select\"\n		>\n										<option\n					value=\"\"\n					data-label=\"Type\"\n					data-counter-prefix=\"\"\n					data-counter-suffix=\"\"\n														>\n					Type				</option>\n								<option\n					value=\"Sports Cruiser \"\n					data-label=\"sports-cruiser \"\n					data-counter-prefix=\"\"\n					data-counter-suffix=\"\"\n														>\n					sports-cruiser 				</option>\n								<option\n					value=\"sedan-bridge \"\n					data-label=\"Sedan Bridge \"\n					data-counter-prefix=\"\"\n					data-counter-suffix=\"\"\n														>\n					Sedan Bridge 				</option>\n								<option\n					value=\"cockpit-motor-yacht \"\n					data-label=\"Cockpit Motor Yacht \"\n					data-counter-prefix=\"\"\n					data-counter-suffix=\"\"\n														>\n					Cockpit Motor Yacht 				</option>\n								<option\n					value=\"motor-yacht \"\n					data-label=\"Motor Yacht \"\n					data-counter-prefix=\"\"\n					data-counter-suffix=\"\"\n														>\n					Motor Yacht 				</option>\n				</select>\n					Check In				\n	<fieldset>\n		<legend style=\"display:none;\">Check In</legend>\n		<input\n			class=\"jet-date-range__from jet-date-range__control\"\n			type=\"text\"\n			autocomplete=\"off\"\n			placeholder=\"Date\"\n			name=\"yacht-check-in_from\"\n			value=\"\"\n			aria-label=\"Date range from\"\n					>\n		<input\n			class=\"jet-date-range__to jet-date-range__control\"\n			type=\"text\"\n			autocomplete=\"off\"\n			placeholder=\"Date\"\n			name=\"yacht-check-in_to\"\n			value=\"\"\n			aria-label=\"Date range to\"\n					>\n	</fieldset>\n	<input\n		class=\"jet-date-range__input\"\n		type=\"hidden\"\n		name=\"yacht-check-in\"\n		value=\"\"\n		aria-label=\"Date range value\"\n		data-date-format=\"\"\n			>\n		<button\n		type=\"button\"\n		class=\"jet-date-range__submit apply-filters__button\"\n			>\n			</button>\n					Check Out				\n	<fieldset>\n		<legend style=\"display:none;\">Check In</legend>\n		<input\n			class=\"jet-date-range__from jet-date-range__control\"\n			type=\"text\"\n			autocomplete=\"off\"\n			placeholder=\"Date\"\n			name=\"yacht-check-in_from\"\n			value=\"\"\n			aria-label=\"Date range from\"\n					>\n		<input\n			class=\"jet-date-range__to jet-date-range__control\"\n			type=\"text\"\n			autocomplete=\"off\"\n			placeholder=\"Date\"\n			name=\"yacht-check-in_to\"\n			value=\"\"\n			aria-label=\"Date range to\"\n					>\n	</fieldset>\n	<input\n		class=\"jet-date-range__input\"\n		type=\"hidden\"\n		name=\"yacht-check-in\"\n		value=\"\"\n		aria-label=\"Date range value\"\n		data-date-format=\"\"\n			>\n		<button\n		type=\"button\"\n		class=\"jet-date-range__submit apply-filters__button\"\n			>\n			</button>\n					Guests				\n				<select\n			class=\"jet-select__control\"\n			name=\"yacht-guests\"\n						aria-label=\"Guests\"\n		>\n										<option\n					value=\"\"\n					data-label=\"Number\"\n					data-counter-prefix=\"\"\n					data-counter-suffix=\"\"\n														>\n					Number				</option>\n								<option\n					value=\"2\"\n					data-label=\"2\"\n					data-counter-prefix=\"\"\n					data-counter-suffix=\"\"\n														>\n					2				</option>\n								<option\n					value=\"3\"\n					data-label=\"3\"\n					data-counter-prefix=\"\"\n					data-counter-suffix=\"\"\n														>\n					3				</option>\n								<option\n					value=\"4\"\n					data-label=\"4\"\n					data-counter-prefix=\"\"\n					data-counter-suffix=\"\"\n														>\n					4				</option>\n				</select>\n	<button\n		type=\"button\"\n		class=\"apply-filters__button\"\n					>\n		Search	</button>\n					<h6>Luxury APARTMENTS</h6>					<h2>Featured</h2>															<img src=\"http://localhost:8888/viktorin/wp-content/uploads/elementor/thumbs/viktorin-icon-rq6wjydl9zuc40l2h6dpw1ojbkyh4j3y4gvij8gx8c.png\" title=\"viktorin-icon\" alt=\"viktorin-icon\" loading=\"lazy\" />																<style>.elementor-97 .elementor-element.elementor-element-ed14082 .elementor-repeater-item-9febe37.jet-parallax-section__layout .jet-parallax-section__image{background-size:auto;}.elementor-97 .elementor-element.elementor-element-fa55f67{--spacer-size:300px;}.elementor-97 .elementor-element.elementor-element-ed14082:not(.elementor-motion-effects-element-type-background), .elementor-97 .elementor-element.elementor-element-ed14082 > .elementor-motion-effects-container > .elementor-motion-effects-layer{background-color:#FFFFFF;background-position:center left;background-repeat:no-repeat;background-size:cover;}.elementor-97 .elementor-element.elementor-element-ed14082, .elementor-97 .elementor-element.elementor-element-ed14082 > .elementor-background-overlay{border-radius:10px 10px 0px 0px;}.elementor-97 .elementor-element.elementor-element-ed14082{transition:background 0.3s, border 0.3s, border-radius 0.3s, box-shadow 0.3s;}.elementor-97 .elementor-element.elementor-element-ed14082 > .elementor-background-overlay{transition:background 0.3s, border-radius 0.3s, opacity 0.3s;}.elementor-97 .elementor-element.elementor-element-c68b8b2 .elementor-repeater-item-224de44.jet-parallax-section__layout .jet-parallax-section__image{background-size:auto;}.elementor-97 .elementor-element.elementor-element-f5b38c5 .elementor-repeater-item-5e5314a.jet-parallax-section__layout .jet-parallax-section__image{background-size:auto;}.elementor-97 .elementor-element.elementor-element-9849884 .jet-listing-dynamic-link__link{align-self:flex-start;color:#000000;flex-direction:row;}.elementor-97 .elementor-element.elementor-element-9849884 .jet-listing-dynamic-link__link:hover{color:#FFC389;}.elementor-97 .elementor-element.elementor-element-9849884 .jet-l