INSERT INTO `wp_posts` VALUES (434,1,'2020-05-12 07:32:15','2020-05-12 07:32:15','<p>JERSEY CITY, NJ </p>		\n			<h1>Beckoned</h1>		\n		<img width=\"44\" height=\"44\" src=\"https://jupiterx.artbees.net/yacht-rental/wp-content/uploads/sites/415/2020/05/price-icon-home.svg\" alt=\"\" loading=\"lazy\" />		\n			$625 &nbsp;per day		\n												<img width=\"47\" height=\"44\" src=\"https://jupiterx.artbees.net/yacht-rental/wp-content/uploads/sites/415/2020/05/book-icon-home.svg\" alt=\"\" loading=\"lazy\" />														\n			<p>Book a Yacht</p>		\n			Yacht Type		\n		<select\n			class=\"jet-select__control\"\n			name=\"yacht-types\"\n		>\n					<option\n				value=\"\"\n				data-label=\"Type\"\n				data-counter-prefix=\"(\"\n				data-counter-suffix=\")\"\n							>Type</option>\n						<option\n				value=\"Sports Cruiser \"\n				data-label=\"sports-cruiser \"\n				data-counter-prefix=\"(\"\n				data-counter-suffix=\")\"\n							>sports-cruiser </option>\n						<option\n				value=\"sedan-bridge \"\n				data-label=\"Sedan Bridge \"\n				data-counter-prefix=\"(\"\n				data-counter-suffix=\")\"\n							>Sedan Bridge </option>\n						<option\n				value=\"cockpit-motor-yacht \"\n				data-label=\"Cockpit Motor Yacht \"\n				data-counter-prefix=\"(\"\n				data-counter-suffix=\")\"\n							>Cockpit Motor Yacht </option>\n						<option\n				value=\"motor-yacht \"\n				data-label=\"Motor Yacht \"\n				data-counter-prefix=\"(\"\n				data-counter-suffix=\")\"\n							>Motor Yacht </option>\n			</select>\n			Check In		\n		<input\n			class=\"jet-date-range__from jet-date-range__control\"\n			type=\"text\"\n			autocomplete=\"off\"\n			placeholder=\"Date\"\n			name=\"yacht-check-in_from\"\n			value=\"\"\n		>\n		<input\n			class=\"jet-date-range__to jet-date-range__control\"\n			type=\"text\"\n			autocomplete=\"off\"\n			placeholder=\"Date\"\n			name=\"yacht-check-in_to\"\n			value=\"\"\n		>\n	<input\n		class=\"jet-date-range__input\"\n		type=\"hidden\"\n		name=\"yacht-check-in\"\n		value=\"