INSERT INTO `wp_posts` VALUES (437,1,'2020-05-13 05:31:27','2020-05-13 05:31:27','<h1>Contact</h1>		\n			<h2>Get in Touch</h2>		\n		<p>In enim justo, rhoncus ut, imperdiet a, venenatis vitae, justo. Pellentesque habitant morbi tristique senectus.</p>		\n			<h4>Address</h4>		\n								<p>Patricia C. Amedee 4401 Waldeck Street Grapevine Nashville, TX 76051</p>\n				<a href=\"mailto:info@yourdomain.com\">\n								</a>\n					<a href=\"mailto:info@yourdomain.com\"></a>\n								<p>info@yourdomain.com</p>\n				<a href=\"tel:+9901010000888\">\n								</a>\n					<a href=\"tel:+9901010000888\"></a>\n								<p>+99 (0) 101 0000 888</p>\n			<h4>Social Media</h4>		\n							<a href=\"https://www.instagram.com/artbees/\" target=\"_blank\" rel=\"noopener noreferrer\">\n					Instagram\n									</a>\n							<a href=\"https://twitter.com/artbees_design\" target=\"_blank\" rel=\"noopener noreferrer\">\n					Twitter\n									</a>\n			<h4>Send Us a Message</h4>		\n					<form method=\"post\" name=\"New form\">\n			<input type=\"hidden\" name=\"post_id\" value=\"169\" />\n			<input type=\"hidden\" name=\"form_id\" value=\"4f03f7e\" />\n					<label\n			for=\"form-field-e086033\"\n			class=\"raven-field-label\">\n			Name *			</label>\n				<input\n			oninput=\"onInvalidRavenFormField(event)\"\n			oninvalid=\"onInvalidRavenFormField(event)\"\n			type=\"text\" name=\"fields[e086033]\" id=\"form-field-e086033\" placeholder=\"\" data-type=\"text\">\n					<label\n			for=\"form-field-2258fee\"\n			class=\"raven-field-label\">\n			Phone *			</label>\n				<input\n			oninput=\"onInvalidRavenFormField(event)\"\n			oninvalid=\"onInvalidRavenFormField(event)\"\n			type=\"tel\" name=\"fields[2258fee]\" id=\"form-field-2258fee\" placeholder=\"\" data-type=\"tel\" pattern=\"^[0-9-+s()]*$\" title=\"The value should only consist numbers and phone characters (-, +, (), etc)\">\n					<label\n			for=\"form-field-4899cfc\"\n			class=\"raven-field-label\">\n			Email Address			</label>\n				<input\n			oninput=